    let mut score = post_residual as f64;

    if bin_residual == bin_capacity {
        score -= 30.0;
    }

    let lookahead = next_item_size as f64;
    if lookahead > 0.0 {
        if post_residual >= lookahead {
            score -= 24.0;
        } else {
            let deficit = lookahead - post_residual as f64;
            score += 0.65 * deficit;
            if post_residual < 10.0 {
                score += 12.0;
            }
        }
    } else {
        score += 0.22 * post_residual as f64;
    }

    let mean = mean_residual.max(0.0);
    let relative = post_residual as f64 - mean;
    score += 0.38 * relative;

    if post_residual < item_size {
        score += 18.0;
    } else if post_residual < next_item_size && next_item_size > 0 {
        score += 10.0;
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };
    score -= 3.0 * progress;

    if open_bins_count > 1 {
        score += 0.015 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let isz = item_size as f64;
    let nxt = next_item_size as f64;
    let ratio = isz / cap;

    // ---- 1. Wasted space penalty: fragments left behind that are too small to use.
    // Dead space is harmful when it cannot host any plausible future item.
    // Estimate the smallest likely future item from the mean residual / stream position.
    let min_useful = 10.0f64.min(cap * 0.12);
    if post_residual > 0.0 && (post_residual as f64) < min_useful {
        // hard dead zone: strongly penalize
        score += 30.0 + 40.0 * (1.0 - (post_residual as f64) / min_useful);
    } else if post_residual > 0.0 {
        // proportional waste: residual larger than a plausible minimum is also waste
        // but less severe; scale by how far from "clean" fills it is.
        score += 6.0 * (post_residual as f64) / cap;
    }

    // ---- 2. Lookahead (k=2): prefer placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            // great: next item can also fit here -> reward
            score -= 18.0 * (next_item_size as f64 / cap);
            // tighter coupling: the more of the next item we can still absorb, the better
            score -= 12.0 * ((post_residual as f64) - nxt) / cap;
        } else {
            // next item will NOT fit: mild penalty, but smaller if the shortfall is small
            let gap = nxt - (post_residual as f64);
            score += 8.0 * gap / cap;
        }
    }

    // ---- 3. Global state: mean residual across open bins.
    // If bins are generally roomy, we should avoid creating a new one and prefer
    // filling existing ones (penalize waste relative to the population average).
    // If bins are generally tight (mean residual low), dead space is less costly.
    let mr = mean_residual.max(0.0);
    let rel = (post_residual as f64) - mr;
    score += 5.0 * rel / cap;

    // ---- 4. Last-chance signal: if this is the only bin that can hold the item,
    // we must use it (unless a fresh bin is clearly better).
    if fitting_bins_count <= 1 {
        score -= 14.0 * ratio;
    }

    // ---- 5. New-bin candidate: bin_residual == bin_capacity (empty bin).
    // Opening a new bin wastes one bin slot: penalize unless the current item is
    // large relative to typical residuals (i.e., existing bins are poor hosts).
    if bin_residual >= bin_capacity {
        // cost of opening
        score += 26.0;
        // If the item is large, opening a fresh bin is often better than cramming
        // it into a nearly-full bin and leaving a tiny unusable remainder.
        score -= 16.0 * ratio;
        // If the next item is also large and cannot be accommodated elsewhere,
        // a fresh bin is more attractive.
        if next_item_size > 0 {
            score -= 6.0 * (nxt / cap) * (1.0 - mr / cap);
        }
    } else {
        // Existing bin: prefer reasonably tight fits (higher fill ratio).
        let fill = (isz / bin_residual.max(1) as f64).min(1.0);
        score -= 10.0 * fill * (1.0 - mr / cap);
        // If many bins are open and they are mostly roomy, packing efficiency matters more.
        if open_bins_count > 1 {
            score -= 4.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - mr / cap);
        }
    }

    // ---- 6. Dynamic time horizon: early in the stream we can afford experimentation
    // and keep bins "clean" for future items; later, consolidation dominates.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    let horizon = 1.0 - t; // 1 early -> 0 late
    // Early: weight lookahead and waste control less? Actually early we want to
    // preserve big clean bins: penalize filling a roomy bin too early.
    score += 8.0 * horizon * ((post_residual as f64) / cap) * (1.0 - ratio);

    // ---- 7. Exact-fit bonus: leaving zero residual is ideal (no waste at all).
    if post_residual == 0 {
        score -= 12.0;
    }

    // ---- 8. Non-linear coupling: reward mid-range "sweet spot" residuals that can
    // plausibly accept a median-sized future item (~40 for C=100).
    if post_residual > 0 {
        let d = ((post_residual as f64) - 40.0).abs() / 40.0;
        score += 4.0 * d;
    }

    // ---- 9. Keep the raw residual as a gentle tiebreaker baseline.
    score += 0.35 * (post_residual as f64) / cap * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let dead_threshold = 10.0_f64.min(item_size as f64 * 0.25);
    if (post_residual as f64) < dead_threshold {
        score += 45.0 - 2.0 * post_residual as f64;
    }

    if next_item_size > 0 {
        if post_residual < next_item_size as u32 {
            score += 8.0 * (next_item_size - post_residual) as f64;
        } else {
            score -= 6.0;
        }
    }

    if fitting_bins_count <= 1 {
        score -= 18.0;
    }

    if bin_residual == bin_capacity {
        score += 22.0;
    }

    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 0.35;

    let residual_penalty = (mean_residual - post_residual as f64).abs();
    score += residual_penalty * 0.08;

    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
