        score -= 45.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    } else {
        if post_residual == 0 {
            score -= 130.0;
        } else if post_residual < item_size {
            score -= 55.0;
        } else if post_residual < next_item_size && next_item_size > 0 {
            score -= 25.0;
