        let harmonic_next = (next_class.max(1)).rem_euclid(capacity_class.max(1));

        score += 7.5 * harmonic_residual as f64;
        score -= 6.0 * harmonic_next as f64;

        let residual_ratio = post_residual as f64 / bin_capacity.max(1) as f64;
        score += 35.0 * residual_ratio * residual_ratio;

        if fitting_bins_count <= 1 {
            score -= 180.0;
        } else if fitting_bins_count == 2 {
            score -= 35.0;
        }

        let mean_gap = mean_residual - post_residual as f64;
        score -= 0.75 * mean_gap;

        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 30.0;
            } else {
                score += 18.0;
            }
        }

        if post_residual % 20 == 0 {
            score -= 4.0;
        }
        if post_residual % 25 == 0 {
            score -= 6.0;
        }
    }

    score
}

