pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let mean = mean_residual.max(0.0);
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 + 1.0) / total_items as f64
    };
    let horizon = (1.0 - progress).clamp(0.0, 1.0);

    let waste_fraction = (post_residual as f64 / capacity).clamp(0.0, 1.0);
    let fill_fraction = (1.0 - waste_fraction).clamp(0.0, 1.0);

    score += 18.0 * waste_fraction * waste_fraction;
    score -= 10.0 * fill_fraction;

    let deviation = (residual - mean).abs();
    score += 0.07 * deviation * (1.0 + open_bins_count as f64).sqrt();

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 16.0;
        score += 0.12 * post_residual as f64;
    }

    if next_item_size > 0 {
        let next = next_item_size as f64;
        let next_fits = (post_residual as f64 + 0.5) >= next;
        let next_slack = post_residual as f64 - next;

        score += 0.055 * next.abs();
        if next_fits {
            score -= 9.0;
            score -= 0.045 * next_slack.max(0.0);
        } else {
            score += 7.0;
            score += 0.035 * next_slack.abs();
        }

        if item >= 45.0 && next <= 30.0 {
            score -= 4.0 * horizon;
        }
    } else {
        score -= 4.0 * progress;
    }

    if bin_residual == bin_capacity {
        score += 24.0;
        score += 6.0 * horizon;
        score -= 0.8 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        if next_item_size == 0 {
            score -= 18.0;
        }
    } else if post_residual < item.min(next_item_size.max(item_size)) {
        score += 6.0 + 3.0 * waste_fraction;
    }

    let imbalance = (post_residual as f64 - mean).abs() / capacity;
    score += 3.5 * imbalance * (0.35 + 0.65 * horizon);

